// Curated fixtures and regressions; generated files remain local under /bruno.
export function buildJourneys({endpoints,addCase,bodyFor}) {
  const by=(controller,fn)=>{const e=endpoints.find(e=>e.controller===controller&&e.fn===fn);if(!e)throw Error('Missing endpoint '+controller+'.'+fn);return e;};
  const route=(method,suffix)=>{const e=endpoints.find(e=>e.method===method&&e.route===suffix);if(!e)throw Error('Missing '+method+' '+suffix);return e;};
  const auth=(method,suffix)=>route(method,'/api/v1/auth'+suffix);
  const roles=['ownerA','ownerB','adminA','techA1','techA2','advisorA1','sellerA1','customerA','customerB','outsider','shared'];
  const capture=(field,name)=>`if (res.status < 300) { const value=res.getBody().data.${field}; if(value===undefined) throw new Error('No se recibió ${field}'); bru.setVar('${name}',value); }`;
  const login=auth('POST','/login');
  for(const actor of ['platformAdmin',...roles]) {
    addCase(login,'LOGIN_'+actor,200,'Login '+actor,{folder:'00-preflight',body:{email:`{{${actor}Email}}`,password:`{{${actor}Password}}`},pre:'Usuario activo y verificado. Ejecutar este login antes de probar con ese actor.',postScript:`if (res.status === 200) { const d=res.getBody().data; bru.setVar('${actor}Token',d.accessToken); bru.setVar('${actor}UserId',d.user.id); const h=res.getHeaders(); const cookies=h['set-cookie']||h['Set-Cookie']||[]; const match=(Array.isArray(cookies)?cookies:[cookies]).join(';').match(/tm_refresh=([^;]+)/); if(!match) throw new Error('Falta cookie tm_refresh'); bru.setVar('${actor}RefreshToken',match[1]); }`,tests:"test('Refresh no expuesto en JSON',()=>expect(res.getBody().data).not.to.have.property('refreshToken'));"});
  }
  for(const actor of roles) {
    const body=bodyFor('RegisterRequest');body.email=`{{${actor}Email}}`;body.password=`{{${actor}Password}}`;body.documentNumber=`{{${actor}DocumentNumber}}`;body.name='QA '+actor;
    addCase(auth('POST','/register'),'REGISTER_'+actor,201,'Registrar '+actor,{folder:'02-usuarios',body,blocked:'Faltan buzones QA: completar correo antes de registrar.',postScript:capture('id',actor+'UserId')});
    addCase(auth('POST','/verify-email'),'VERIFY_'+actor,200,'Verificar '+actor,{folder:'02-usuarios',body:{token:`{{${actor}VerificationToken}}`},blocked:'Introducir token recibido en buzón controlado del actor.'});
  }
  const req=route('POST','/api/v1/business/requests');
  for(const tenant of ['A','B']) {
    const b=bodyFor(req.dto);b.businessName=`QA-${tenant}-{{runId}}`;b.documentNumber=`{{business${tenant}DocumentNumber}}`;b.email=`{{owner${tenant}Email}}`;b.legalFile='{{qaLegalFileUrl}}';
    addCase(req,'REQUEST_'+tenant,201,'Solicitar negocio '+tenant,{folder:'03-negocios',actor:'owner'+tenant,body:b,postScript:capture('id','request'+tenant+'Id')});
    const approve=route('PUT','/api/v1/business/requests/{id}/approve');
    addCase(approve,'APPROVE_'+tenant,200,'Aprobar negocio '+tenant,{folder:'03-negocios',actor:'platformAdmin',url:`{{baseUrl}}/api/v1/business/requests/{{request${tenant}Id}}/approve`});
    addCase(route('GET','/api/v1/businesses/my'),'RESOLVE_'+tenant,200,'Resolver negocio '+tenant,{folder:'03-negocios',actor:'owner'+tenant,postScript:`if(res.status===200){const matches=res.getBody().data.filter(b=>b.name==='QA-${tenant}-'+(bru.getVar('runId')||bru.getEnvVar('runId')));if(matches.length!==1)throw new Error('Se esperaba exactamente un negocio QA ${tenant}');bru.setVar('business${tenant}Id',matches[0].id);}`});
    for(const site of ['1','2']) {
      const branch=route('POST','/api/v1/businesses/{businessId}/branches');const body=bodyFor(branch.dto);body.name=`QA-${tenant}${site}-{{runId}}`;body.primaryBranch=false;
      addCase(branch,'BRANCH_'+tenant+site,201,'Crear sede '+tenant+site,{folder:'03-negocios',actor:'owner'+tenant,url:`{{baseUrl}}/api/v1/businesses/{{business${tenant}Id}}/branches`,body,postScript:capture('id','branch'+tenant+site+'Id')});
    }
  }
  const cat=route('GET','/api/v1/businesses/{businessId}/catalogs/{catalogType}');
  for(const tenant of ['A','B'])for(const type of ['SERVICE_CATEGORY','DEVICE_TYPE','BRAND','REPAIR_ORDER_STATUS','QUOTATION_STATUS','APPOINTMENT_STATUS','MOVEMENT_TYPE','ITEM_CATEGORY','PAYMENT_METHOD'])
    addCase(cat,'CAPTURE_'+tenant+'_'+type,200,'Resolver códigos '+tenant+' '+type,{folder:'03-negocios',actor:'owner'+tenant,url:`{{baseUrl}}/api/v1/businesses/{{business${tenant}Id}}/catalogs/${type}`,postScript:`if(res.status===200){for(const item of res.getBody().data){bru.setVar('${tenant}_${type}_'+item.code,item.id);}}`});
  const roleCreate=route('POST','/api/v1/parameters/roles');
  for(const code of ['ALLOW','DENY'])addCase(roleCreate,'QA_ROLE_'+code,201,'Crear rol QA '+code,{folder:'03-negocios',actor:'platformAdmin',body:{code:`QA_${code}_{{runId}}`,name:'Rol QA '+code,description:'Exclusivo de esta ejecución QA',scope:'BUSINESS'},postScript:capture('id','role'+code+'Id')});
  const perms=route('PUT','/api/v1/parameters/roles/{roleId}/permissions');
  addCase(perms,'QA_ALLOW',200,'Asignar QUOTATION_VIEW al rol QA ALLOW',{folder:'03-negocios',actor:'platformAdmin',url:'{{baseUrl}}/api/v1/parameters/roles/{{roleALLOWId}}/permissions',body:{permissionIds:['{{quotationViewPermissionId}}']}});
  addCase(perms,'QA_DENY',200,'Vaciar permisos del rol QA DENY',{folder:'03-negocios',actor:'platformAdmin',url:'{{baseUrl}}/api/v1/parameters/roles/{{roleDENYId}}/permissions',body:{permissionIds:[]}});
  addCase(perms,'REJECT_GLOBAL',409,'Rechazar permiso GLOBAL en rol BUSINESS',{folder:'06-aislamiento',actor:'platformAdmin',url:'{{baseUrl}}/api/v1/parameters/roles/{{roleALLOWId}}/permissions',body:{permissionIds:['{{globalPermissionId}}']},pre:'globalPermissionId corresponde a BUSINESS_REQUEST_REVIEW con scope GLOBAL; guardar permisos originales de QA_ALLOW y comprobar que permanecen intactos.'});
  const membership=route('POST','/api/v1/businesses/{businessId}/users');
  const members=[['adminA','A',['1','2'],'BUSINESS_ADMIN'],['techA1','A',['1'],'TECHNICIAN'],['techA2','A',['2'],'TECHNICIAN'],['advisorA1','A',['1'],'RECEPTIONIST'],['sellerA1','A',['1'],'SELLER'],['shared','A',['1'],'ALLOW'],['shared','B',['1'],'DENY']];
  for(const [actor,tenant,sites,role] of members)addCase(membership,'MEMBER_'+actor+'_'+tenant,201,`Asignar ${actor} a ${tenant}`,{folder:'03-negocios',actor:'owner'+tenant,url:`{{baseUrl}}/api/v1/businesses/{{business${tenant}Id}}/users`,body:{userId:`{{${actor}UserId}}`,roleId:`{{role${role}Id}}`,branchIds:sites.map(s=>`{{branch${tenant}${s}Id}}`),commissionPercentage:role==='TECHNICIAN'?20:0},postScript:capture('id',actor+tenant+'BusinessUserId')});
  // Ordered pilot uses selected tenant-specific inputs; no fabricated IDs.
  const steps=[['CustomerDeviceController','create'],['BusinessOfferingController','create'],['BusinessQualityTestController','create'],['InventoryItemController','create'],['RepairOrderController','create'],['RepairOrderController','updateDiagnosis'],['QuotationController','create']];
  for(const [controller,fn] of steps){const e=by(controller,fn);addCase(e,'PILOT',e.http,e.summary,{folder:'04-piloto',actor:'ownerA',pre:'Completar variables.md para A1. Usar datos nuevos de este recorrido; registrar el ID devuelto.',postScript:capture('id',controller.replace('Controller','')+'PilotId')});}
  const state=route('PATCH','/api/v1/businesses/{businessId}/repair-orders/{repairOrderId}/status');
  for(const target of ['DIAGNOSIS','WAITING_APPROVAL','WAITING_PARTS','REPAIRING','TESTING','READY_FOR_PICKUP','DELIVERED'])addCase(state,'FLOW_'+target,200,'Transición a '+target,{folder:'04-piloto',actor:'ownerA',body:{statusId:`{{A_REPAIR_ORDER_STATUS_${target}}}`,comment:'QA transición '+target,visibility:'INTERNAL'},pre:target==='DELIVERED'?'Orden READY_FOR_PICKUP y finalPrice establecido; actor con REPAIR_ORDER_CLOSE.':'Seguir la secuencia del README; no ejecutar esta carpeta completa sin intercalar cotización, piezas y pruebas.'});
  addCase(state,'JUMP_DELIVERED',409,'Prohibir RECEIVED a DELIVERED',{folder:'06-aislamiento',actor:'ownerA',body:{statusId:'{{A_REPAIR_ORDER_STATUS_DELIVERED}}'},pre:'Orden nueva RECEIVED exclusiva de este caso. ownerA dispone de CLOSE. Precio final configurado antes del intento; comprobar estado e historial sin cambios.'});
  addCase(state,'TECH_CLOSE',403,'Técnico no entrega orden',{folder:'06-aislamiento',actor:'techA1',body:{statusId:'{{A_REPAIR_ORDER_STATUS_DELIVERED}}'},pre:'Orden A1 READY_FOR_PICKUP con precio final. techA1 asignado a A1 con UPDATE pero sin CLOSE.'});
  const fin=route('PATCH','/api/v1/businesses/{businessId}/repair-orders/{repairOrderId}/financials');
  addCase(fin,'TECH_PRICE',403,'Técnico no cambia precio',{folder:'06-aislamiento',actor:'techA1',body:{finalPrice:100},pre:'Orden mutable A1; técnico con UPDATE y sin FINANCIAL_UPDATE. Guardar precio e historial antes.'});
  const quotation=by('QuotationController','findById');
  addCase(quotation,'OTHER_BRANCH',403,'Cotización A2 inaccesible a técnico A1',{folder:'06-aislamiento',actor:'techA1',url:'{{baseUrl}}/api/v1/businesses/{{businessAId}}/quotations/{{quotationA2Id}}',pre:'Cotización existente de orden A2. techA1 tiene QUOTATION_VIEW en A pero solo sede A1.'});
  addCase(quotation,'SHARED_SCOPE',403,'Permiso obtenido en A no habilita B',{folder:'06-aislamiento',actor:'shared',url:'{{baseUrl}}/api/v1/businesses/{{businessBId}}/quotations/{{quotationB1Id}}',pre:'shared tiene rol QA con QUOTATION_VIEW en A y rol QA vacío en B; asignado a A1/B1; login nuevo después de asignaciones.'});
  const inv=by('InventoryItemController','findById');
  addCase(inv,'OTHER_BRANCH',403,'Inventario A2 inaccesible a técnico A1',{folder:'06-aislamiento',actor:'techA1',url:'{{baseUrl}}/api/v1/businesses/{{businessAId}}/inventory-items/{{inventoryA2Id}}'});
  addCase(inv,'NO_COST',200,'Ocultar costo a técnico',{folder:'06-aislamiento',actor:'techA1',tests:"test('Sin costo financiero',()=>expect(res.getBody().data).not.to.have.property('unitCost'));",pre:'techA1 con INVENTORY_VIEW sin INVENTORY_COST_VIEW, artículo A1.'});
  const meOrder=endpoints.find(e=>e.controller==='CustomerRepairOrderController');
  addCase(meOrder,'OTHER_CUSTOMER',404,'Cliente B no ve orden de cliente A',{folder:'06-aislamiento',actor:'customerB',pre:'orderNumber de una orden cuyo cliente es customerA. customerB tiene token válido.'});
  const pubReviews=route('GET','/api/v1/public/businesses/{businessId}/reviews');
  addCase(pubReviews,'EXACT_PRIVACY',200,'JSON público exacto de reseñas',{folder:'08-funciones-adicionales',tests:"test('Lista pública limitada',()=>{const data=res.getBody().data;const items=Array.isArray(data)?data:data.items;expect(items.length).to.be.greaterThan(0);for(const item of items)expect(Object.keys(item).sort()).to.deep.equal(['comment','createdAt','customerDisplayName','rating'].sort());});",pre:'Marketplace habilitado y reseña QA existente; sin Authorization.'});
  const refresh=auth('POST','/refresh');
  addCase(refresh,'ROTATE',200,'Rotar refresh de sesión QA',{folder:'07-identidad',headers:{Cookie:'tm_refresh={{sessionRefreshToken}}'},pre:'Login QA dedicado; copiar su refresh a sessionRefreshToken y token a sessionAccessToken. Deshabilitar cookie jar automático.',postScript:"if(res.status===200){bru.setVar('previousRefreshToken',bru.getVar('sessionRefreshToken')||bru.getEnvVar('sessionRefreshToken'));const h=res.getHeaders();const c=h['set-cookie']||h['Set-Cookie']||[];const m=(Array.isArray(c)?c:[c]).join(';').match(/tm_refresh=([^;]+)/);if(!m)throw new Error('Falta cookie rotada');bru.setVar('sessionRefreshToken',m[1]);bru.setVar('sessionAccessToken',res.getBody().data.accessToken);}"});
  addCase(refresh,'REPLAY',401,'Reusar refresh anterior',{folder:'07-identidad',headers:{Cookie:'tm_refresh={{previousRefreshToken}}'},pre:'Ejecutar ROTATE; no refrescar automáticamente tras el error. La familia debe quedar revocada.'});
  addCase(auth('GET','/me'),'AFTER_REPLAY',401,'Access token de familia revocada',{folder:'07-identidad',headers:{Authorization:'Bearer {{sessionAccessToken}}'},pre:'Ejecutar REPLAY; usar el access token emitido por ROTATE.'});
  addCase(refresh,'MISSING_COOKIE',400,'Refresh sin cookie',{folder:'07-identidad',headers:{Cookie:null},pre:'Cookie jar automático deshabilitado; Origin permitido.'});
  addCase(refresh,'BAD_ORIGIN',403,'Refresh con Origin ajeno',{folder:'07-identidad',headers:{Origin:'https://qa-untrusted.invalid',Cookie:'tm_refresh={{sessionRefreshToken}}'},pre:'REFRESH_COOKIE_REQUIRE_ORIGIN=true y sesión QA nueva válida.'});
  addCase(login,'RATE_LIMIT',429,'Sexto intento mismo correo e IP',{folder:'07-abuso',body:{email:'{{qaAbuseEmail}}',password:'wrong-qa-password'},pre:'Correo QA inexistente controlado; ventana limpia de 60 s. Enviar cinco intentos previos con mismo body y comprobar 401; sexto antes de 60 s. No mezclar con otras pruebas de login.',tests:"test('Retry-After',()=>{const h=res.getHeaders();expect(String(h['retry-after']||h['Retry-After'])).to.equal('60');});"});
  const userStatus=route('PATCH','/api/v1/parameters/users/{id}/status');
  addCase(userStatus,'DEACTIVATE_QA',200,'Desactivar usuario QA con sesión abierta',{folder:'07-identidad',actor:'platformAdmin',url:'{{baseUrl}}/api/v1/parameters/users/{{qaSessionUserId}}/status',body:{active:false},pre:'Cuenta QA dedicada, nunca administrador de bootstrap; guardar su access y refresh en sessionAccessToken/sessionRefreshToken antes.'});
  for(const reason of ['DEACTIVATION','PASSWORD_CHANGE','PASSWORD_RESET','LOGOUT','REVOKE_ONE','REVOKE_ALL','ROLE_CHANGE']) {
    addCase(auth('GET','/me'),'INVALID_AFTER_'+reason,401,'Access inválido tras '+reason,{folder:'07-identidad',headers:{Authorization:'Bearer {{sessionAccessToken}}'},pre:`Sesión QA nueva. Ejecutar la acción ${reason} según identidad-integridad.md. No iniciar sesión ni sustituir sessionAccessToken entre acción y comprobación.`});
    addCase(refresh,'INVALID_AFTER_'+reason,401,'Refresh inválido tras '+reason,{folder:'07-identidad',headers:{Cookie:'tm_refresh={{sessionRefreshToken}}'},pre:`Sesión QA nueva afectada por ${reason}; conservar refresh anterior y Origin válido; cookie jar desactivado.`});
  }
  for(const e of endpoints.filter(e=>e.params.some(p=>p.annotations.some(a=>a.name==='RequestHeader'&&a.args.includes('Idempotency-Key'))))) {
    addCase(e,'IDEMPOTENT_FIRST',e.http,'Primera ejecución idempotente',{folder:'08-integridad',headers:{'Idempotency-Key':'{{idempotencyKey}}'},pre:'Fixture nuevo, clave única por caso, guardar body exacto y contadores previos.',postScript:capture('id','idempotentResourceId')});
    addCase(e,'IDEMPOTENT_REPLAY',e.http,'Reintento con mismo body y clave',{folder:'08-integridad',headers:{'Idempotency-Key':'{{idempotencyKey}}'},tests:"test('Mismo recurso',()=>expect(res.getBody().data.id).to.equal(Number(bru.getVar('idempotentResourceId')||bru.getEnvVar('idempotentResourceId'))));",pre:'Ejecutar IDEMPOTENT_FIRST de este mismo endpoint; no cambiar body, actor, tenant ni clave. Comprobar que stock/historial no se duplicaron.'});
    const body=bodyFor(e.dto);const field=body.quantity!==undefined?'quantity':body.problemDescription!==undefined?'problemDescription':body.notes!==undefined?'notes':null;
    if(field){body[field]=field==='quantity'?2:'Contenido diferente para misma clave';addCase(e,'IDEMPOTENT_CONFLICT',409,'Misma clave con body diferente',{folder:'08-integridad',body,headers:{'Idempotency-Key':'{{idempotencyKey}}'},pre:'Ejecutar FIRST; cambiar únicamente campo indicado; conservar actor y clave. Comparar estado antes/después.'});}
  }
  for(const [controller,field,foreign] of [['QuotationController','repairOrderId','repairOrderB1Id'],['CustomerDeviceController','deviceTypeId','deviceTypeBId'],['InventoryItemController','itemCategoryId','itemCategoryBId'],['RepairOrderController','customerDeviceId','deviceBId']]) {
    const e=by(controller,'create');addCase(e,'BODY_FOREIGN_ID',404,'Rechazar relación de otro negocio en body',{folder:'06-aislamiento',actor:'ownerA',body:{...bodyFor(e.dto),[field]:`{{${foreign}}}`},pre:'URL businessId=A; todos los campos pertenecen a A salvo el campo alterado que pertenece a B. ID de B existente y activo.'});
  }
  const branchResource=route('GET','/api/v1/businesses/{businessId}/branches/{branchId}');
  addCase(branchResource,'PATH_FOREIGN_BRANCH',404,'Sede B bajo ruta de negocio A',{folder:'06-aislamiento',actor:'ownerA',url:'{{baseUrl}}/api/v1/businesses/{{businessAId}}/branches/{{branchB1Id}}'});
  const inventoryCreate=by('InventoryItemController','create');
  addCase(inventoryCreate,'DUPLICATE_SKU',409,'SKU repetido en mismo negocio',{folder:'08-integridad',actor:'ownerA',pre:'Crear antes artículo con mismo sku en negocio A; nueva clave no evita unicidad. Debe conservarse cantidad del original.'});
  const rev=route('POST','/api/v1/businesses/{businessId}/reviews');
  addCase(rev,'NOT_DELIVERED',409,'Reseña antes de entrega',{folder:'08-funciones-adicionales',actor:'customerA',pre:'Orden propia customerA que no está DELIVERED; ninguna reseña existente.'});
  addCase(rev,'DUPLICATE_REVIEW',409,'Segunda reseña de misma orden',{folder:'08-funciones-adicionales',actor:'customerA',pre:'Orden propia DELIVERED con una reseña; comprobar ratingCount sin aumento.'});
  // A fresh order is required for every matrix cell (not sequentially reused).
  const repairStates=['RECEIVED','DIAGNOSIS','WAITING_APPROVAL','WAITING_PARTS','REPAIRING','TESTING','READY_FOR_PICKUP','DELIVERED','CANCELLED'];
  const edges={RECEIVED:['DIAGNOSIS'],DIAGNOSIS:['WAITING_APPROVAL'],WAITING_APPROVAL:['WAITING_PARTS','REPAIRING'],WAITING_PARTS:['REPAIRING'],REPAIRING:['WAITING_PARTS','TESTING'],TESTING:['REPAIRING','READY_FOR_PICKUP'],READY_FOR_PICKUP:['DELIVERED']};
  for(const from of repairStates)for(const to of repairStates){const terminal=['DELIVERED','CANCELLED'].includes(from);const allowed=from===to||(!terminal&&(to==='CANCELLED'||(edges[from]||[]).includes(to)));
    addCase(state,`STATE_${from}_${to}`,allowed?200:409,`${from} a ${to}`,{folder:'08-estados',actor:'ownerA',body:{statusId:`{{A_REPAIR_ORDER_STATUS_${to}}}`,comment:'QA matriz de estados'},pre:`Crear orden exclusiva y llevarla hasta ${from} por ruta válida. Configurar finalPrice suficiente antes de entrega y no liquidar comisiones. Confirmar estado previo inmediatamente antes. No reutilizar orden de otra celda.`});}
  const quotationState=route('PATCH','/api/v1/businesses/{businessId}/quotations/{quotationId}/status');
  const quotationStates=['DRAFT','PENDING','APPROVED','REJECTED','EXPIRED','CANCELLED'];
  for(const from of quotationStates)for(const to of quotationStates){
    const allowed=from===to||(from==='DRAFT'&&['PENDING','CANCELLED'].includes(to))||(from==='PENDING'&&['APPROVED','REJECTED','EXPIRED','CANCELLED'].includes(to));
    addCase(quotationState,`STATE_${from}_${to}`,allowed?200:409,`Cotización ${from} a ${to}`,{folder:'08-estados',actor:'ownerA',body:{...bodyFor(quotationState.dto),statusId:`{{A_QUOTATION_STATUS_${to}}}`},pre:`Cotización nueva exclusiva en estado ${from}, de una orden mutable de A1. Para destino/origen EXPIRED usar expiresAt ya vencido; en las demás celdas, futuro. Llegar al estado previo por transiciones válidas, esperando vencimiento cuando corresponda. Guardar estado e historial previos.`});
  }
  addCase(quotationState,'EXPIRE_TOO_EARLY',409,'No expirar antes de la fecha',{folder:'08-estados',actor:'ownerA',body:{...bodyFor(quotationState.dto),statusId:'{{A_QUOTATION_STATUS_EXPIRED}}'},pre:'Cotización PENDING con expiresAt futuro y orden mutable. Sin cambio de estado ni historial.'});
  addCase(quotationState,'APPROVE_EXPIRED',409,'No aprobar después del vencimiento',{folder:'08-estados',actor:'ownerA',body:{...bodyFor(quotationState.dto),statusId:'{{A_QUOTATION_STATUS_APPROVED}}'},pre:'Cotización PENDING creada con vencimiento futuro; esperar que expiresAt venza sin cambiar el estado. Orden mutable.'});
  const scopedControllers=new Set(['AppointmentController','BusinessCatalogController','BusinessOfferingController','BusinessQualityTestController','BusinessScheduleController','CustomerDeviceController','InventoryItemController','QuotationController','RepairOrderController','RepairOrderHistoryController','RepairOrderAttachmentController','RepairOrderQualityCheckController','RepairOrderPartController','SaleController','StockMovementController']);
  for(const e of endpoints.filter(e=>scopedControllers.has(e.controller)&&e.route.includes('{businessId}')&&/has(Any)?Authority/.test(e.permission))){
    addCase(e,'SHARED_PERMISSION_SCOPE',403,'Permiso de A no autoriza operación en B',{folder:'06-aislamiento',actor:'shared',pre:`Configurar QA_ALLOW en A con los permisos BUSINESS exactos de ${e.id}; QA_DENY en B sin ellos. shared pertenece activamente a A1 y B1. Hacer login NUEVO; /auth/me=200. Configurar TODOS los IDs/body/ruta/filtros con recursos existentes de B y businessId=businessBId. La operación positiva equivalente en A debe funcionar primero. Guardar snapshots de B y comprobar cero mutaciones.`});
    addCase(e,'INACTIVE_MEMBERSHIP',403,'Membresía inactiva no autoriza operación',{folder:'06-aislamiento',actor:'shared',pre:`Fixture exclusivo. shared conserva permiso de ${e.id} en A y membresía activa allí. Asignar temporalmente permiso equivalente en B y comprobar positivo. Desactivar solo su membresía B mediante EP079 con body completo y active=false, hacer login NUEVO y comprobar /auth/me=200. Recurso de B existente, todos los IDs de B. No confundir JWT anterior revocado (401) con este caso. Reactivar B con EP079 active=true y restaurar QA_DENY al cerrar.`});
    addCase(e,'INACTIVE_ROLE',403,'Rol empresarial inactivo no concede permisos',{folder:'06-aislamiento',actor:'shared',pre:`Usar un rol BUSINESS QA nuevo exclusivo para shared en B con el permiso de ${e.id}. Comprobar acceso positivo, desactivar ese rol por EP162 con body completo y active=false y hacer login NUEVO. shared mantiene A activo y su rol QA_ALLOW. /auth/me=200. Todos los IDs del request pertenecen a B. Restaurar rol y QA_DENY al terminar; nunca desactivar roles sembrados.`});
  }
}
